const axios = require('axios');

async function kirimPesanHotbot() {
  const url = 'https://www.hotbot.com/api/chat';
  const data = {
    messages: [{ role: 'user', content: 'hai' }],
    model: 'chatgpt-5',
    chatId: 'bea041e3-6afe-4455-a753-77c92f4c3d9f',
    camp: false
  };
  const headers = {
    'Content-Type': 'application/json'
  };

  try {
    const response = await axios.post(url, data, { headers });

    // Memproses response yang berupa event-stream
    let fullResponse = '';
    response.data.on('data', (chunk) => {
      const lines = chunk.toString().split('\n');
      lines.forEach(line => {
        if (line.startsWith('data: ')) {
          const jsonData = line.substring(6);
          if (jsonData === '[DONE]') {
            // m.reply(fullResponse); // Jika Anda menggunakan bot dengan m.reply
            console.log("Respon lengkap:", fullResponse); // Placeholder jika tidak ada m.reply
          } else {
            try {
              const parsedData = JSON.parse(jsonData);
              if (parsedData.content) {
                fullResponse += parsedData.content;
              }
            } catch (e) {
              console.error("Gagal parse JSON:", jsonData, e);
            }
          }
        }
      });
    });

    response.data.on('end', () => {
      // m.reply(fullResponse); // Jika Anda menggunakan bot dengan m.reply
      console.log("Selesai menerima stream."); // Placeholder jika tidak ada m.reply
    });

    response.data.on('error', (err) => {
      console.error("Error saat menerima stream:", err);
    });

  } catch (error) {
    console.error('Terjadi kesalahan:', error.response ? error.response.data : error.message);
  }
}

kirimPesanHotbot();
